steps.script:
var tv = tree.root.get_node_or_null("TutorialVoice")
if tv == null:
	return "TutorialVoice autoload missing"
if not tv.is_available():
	return "voice unavailable - run tools/generate_tutorial_vo.py to build the clips"
if tv.clip_count() < 100:
	return "manifest too small: " + str(tv.clip_count())
return true

var tv = tree.root.get_node_or_null("TutorialVoice")
if not tv.is_speaking():
	return "narrator silent on the opening card"
var want = "t1_basics__welcome__kbm"
if tv.current_clip_id() != want:
	return "wrong clip: " + str(tv.current_clip_id()) + " expected " + want
return true

var b = tree.root.get_node_or_null("/root/TutorialOverlay/InstructorCard/Margin/VBox/Footer/ReplayVoiceButton")
if b == null:
	return "no replay button on the card"
if not b.visible:
	return "replay button hidden while a clip is loaded"
return true

var tv = tree.root.get_node_or_null("TutorialVoice")
tv.stop()
if tv.is_speaking():
	return "stop() did not stop playback"
return true

var tv = tree.root.get_node_or_null("TutorialVoice")
if not tv.is_speaking():
	return "Say It Again did not restart the line"
if tv.current_clip_id() != "t1_basics__welcome__kbm":
	return "replay played the wrong clip: " + str(tv.current_clip_id())
return true

var tv = tree.root.get_node_or_null("TutorialVoice")
if TutorialManager.current_step_id() != "camera":
	return "step did not advance: " + str(TutorialManager.current_step_id())
if tv.current_clip_id() != "t1_basics__camera__kbm":
	return "clip did not follow the step: " + str(tv.current_clip_id())
if not tv.is_speaking():
	return "narrator silent on the new step"
return true

var idm = tree.root.get_node_or_null("InputDeviceManager")
idm._force_mode(idm.InputMode.PAD)
TutorialManager.refresh_prompt()
return idm.is_pad_active()

var tv = tree.root.get_node_or_null("TutorialVoice")
if TutorialManager.current_step_id() != "camera":
	return "step index moved - this must be a re-render, not an advance"
if tv.current_clip_id() != "t1_basics__camera__pad":
	return "pad swap did not change the spoken line: " + str(tv.current_clip_id())
return true

SettingsService.set_tutorial_voice_enabled(false)
var tv = tree.root.get_node_or_null("TutorialVoice")
if tv.is_speaking():
	return "toggling the setting off left the line playing"
return true

var tv = tree.root.get_node_or_null("TutorialVoice")
TutorialManager.refresh_prompt()
if tv.is_speaking():
	return "a new card spoke while the setting was off"
return true

var tv = tree.root.get_node_or_null("TutorialVoice")
if not tv.is_speaking():
	return "turning the setting back on did not restore the narrator"
return true

var tv = tree.root.get_node_or_null("TutorialVoice")
if tv.is_speaking():
	return "narrator kept talking after the tutorial was exited"
return true
